const fs = require('fs');
const fetch = require('node-fetch');

const API_KEY = process.env.CROSSMINT_API_KEY;
const MINT_URL = 'https://staging.crossmint.com/api/2022-06-09/collections/default/nfts';
const ACTION_URL_BASE = 'https://staging.crossmint.com/api/2022-06-09/actions';

async function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

async function main() {
    let result = {
        actionId: "mock-action-id",
        final_status: "unknown",
        poll_attempts: 0,
        mint_chain: "polygon-amoy"
    };

    if (!API_KEY) {
        result.error = "Missing CROSSMINT_API_KEY";
        fs.writeFileSync('/home/user/poll_result.json', JSON.stringify(result, null, 2));
        return;
    }

    try {
        const mintResponse = await fetch(MINT_URL, {
            method: 'POST',
            headers: {
                'X-API-KEY': API_KEY,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                recipient: "email:demo@example.com:polygon-amoy",
                metadata: {
                    name: "Poll Test NFT",
                    description: "Testing async polling",
                    image: "https://example.com/poll.png"
                }
            })
        });

        if (!mintResponse.ok) {
            const errText = await mintResponse.text();
            throw new Error(`Mint API failed: ${mintResponse.status} ${mintResponse.statusText} - ${errText}`);
        }

        const mintData = await mintResponse.json();
        const actionId = mintData.actionId || mintData.id;

        if (!actionId) {
            throw new Error("No actionId returned from minting");
        }

        result.actionId = actionId;

        let status = "pending";
        for (let i = 0; i < 5; i++) {
            result.poll_attempts++;
            const actionResponse = await fetch(`${ACTION_URL_BASE}/${actionId}`, {
                method: 'GET',
                headers: {
                    'X-API-KEY': API_KEY
                }
            });

            if (!actionResponse.ok) {
                const errText = await actionResponse.text();
                throw new Error(`Action API failed: ${actionResponse.status} ${actionResponse.statusText} - ${errText}`);
            }

            const actionData = await actionResponse.json();
            status = actionData.status;

            if (status !== "pending") {
                break;
            }

            if (i < 4) {
                await sleep(2000);
            }
        }

        result.final_status = status;

    } catch (error) {
        result.error = error.message;
    }

    fs.writeFileSync('/home/user/poll_result.json', JSON.stringify(result, null, 2));
}

main().catch(console.error);

